import boto3
import datetime

def compare_cloudwatch_metrics(
    metric_name: str,
    namespace: str,
    resource_id_1: str,
    resource_id_2: str,
    dimension_key: str,
    start_time: datetime.datetime,
    end_time: datetime.datetime,
    period_seconds: int,
    statistic: str = "Average",
) -> dict:
    """
    Compares metric values for two resources over the same time window using Amazon CloudWatch.

    Args:
        metric_name: The name of the metric to compare (e.g., 'CPUUtilization').
        namespace: The namespace of the metric (e.g., 'AWS/EC2').
        resource_id_1: The ID of the first resource (e.g., 'i-abcdef1234567890a').
        resource_id_2: The ID of the second resource (e.g., 'i-fedcba9876543210f').
        dimension_key: The key for the resource dimension (e.g., 'InstanceId').
        start_time: The start time for the metric data.
        end_time: The end time for the metric data.
        period_seconds: The granularity, in seconds, of the returned data points.
                        For metrics with a one-minute resolution, valid values are
                        60, 300, 900, 3600, and any multiple of 300, 900, 3600.
        statistic: The statistic to apply to the metric data (e.g., 'Average', 'Sum', 'Maximum', 'Minimum', 'SampleCount').

    Returns:
        A dictionary containing the metric data for both resources, with timestamps
        and values for comparison.
    """
    cloudwatch = boto3.client("cloudwatch")

    response = cloudwatch.get_metric_data(
        MetricDataQueries=[
            {
                "Id": "resource1_metric",
                "MetricStat": {
                    "Metric": {
                        "Namespace": namespace,
                        "MetricName": metric_name,
                        "Dimensions": [
                            {"Name": dimension_key, "Value": resource_id_1},
                        ],
                    },
                    "Period": period_seconds,
                    "Stat": statistic,
                },
                "ReturnData": True,
            },
            {
                "Id": "resource2_metric",
                "MetricStat": {
                    "Metric": {
                        "Namespace": namespace,
                        "MetricName": metric_name,
                        "Dimensions": [
                            {"Name": dimension_key, "Value": resource_id_2},
                        ],
                    },
                    "Period": period_seconds,
                    "Stat": statistic,
                },
                "ReturnData": True,
            },
        ],
        StartTime=start_time,
        EndTime=end_time,
    )

    result = {
        "resource1": {"timestamps": [], "values": []},
        "resource2": {"timestamps": [], "values": []},
    }

    for metric_data_result in response["MetricDataResults"]:
        if metric_data_result["Id"] == "resource1_metric":
            result["resource1"]["timestamps"] = [t.isoformat() for t in metric_data_result["Timestamps"]]
            result["resource1"]["values"] = metric_data_result["Values"]
        elif metric_data_result["Id"] == "resource2_metric":
            result["resource2"]["timestamps"] = [t.isoformat() for t in metric_data_result["Timestamps"]]
            result["resource2"]["values"] = metric_data_result["Values"]

    return result
